-- =========================================================================
-- Core Programme track seed
--
-- GENERATED FILE - do not edit by hand.
-- Source: lib/programme/track-spec.ts   Regenerate: npm run seed:programme
--
-- Idempotent: every insert is guarded, so running this twice is a no-op.
-- Run AFTER migrations. Safe to run against an existing track.
--
-- Learn videos are REFERENCED, never copied: learn_video_id is resolved by
-- exact title match against learn_videos and left null when there's no
-- match, to be bound later in the admin Track-items screen.
-- =========================================================================

insert into public.programme_tracks (name, slug, is_active)
select 'Core Programme', 'core-programme', true
 where not exists (select 1 from public.programme_tracks where slug = 'core-programme');

-- 41 items: day 0 gate, 15 x (video + use_example), 3 sessions,
-- 3 quizzes (end of each week), 3 submission slots, 1 post check-in.
with track as (
  select id from public.programme_tracks where slug = 'core-programme'
), spec(type, title, description, day_index, sort_order, learn_video_title, config_json) as (
  values
    ('questionnaire_baseline', 'Your AI Score - 3-minute check-in', 'A quick self-assessment. It sets your starting point and unlocks the programme.', 0, 0, null, '{}'::jsonb),
    ('video', 'What is AI and how does it work?', 'Prediction rather than lookup, the context window, training cutoff vs live data, the three failure sources and Time-Back Log setup.', 1, 0, 'What is AI and how does it work?', '{}'::jsonb),
    ('use_example', 'Task', 'Sign in to Claude with your Phlo email, install the desktop app, then run one real task from this week through it.
Submit the link to that task.', 1, 1, null, '{}'::jsonb),
    ('submission_slot', 'Work sample (before)', null, 1, 4, null, '{"kind":"work_sample_pre","visibility":"private"}'::jsonb),
    ('video', 'When to use AI and when not to', null, 2, 0, 'When to use AI and when not to', '{}'::jsonb),
    ('use_example', 'Task', 'Pick three jobs from this week:
- one you are confident Claude will do well
- one you are confident Claude will not do well
- one where you are not sure whether it will produce the correct output
Before you open Claude, predict each outcome and rate it Certain, Fairly confident or Guessing.
Run all three separately, including the one you expect to fail, and compare the output to your predictions.
If something worked that you expected not to, that is something to delegate to Claude immediately. Something that gave an incorrect output is one to be cautious about and double-check.
If Claude did not produce the output you wanted for a specific task, try again. Add more context, add an example document, or split it into two steps, and see whether that helps.
Submit the link to one of these, preferably the one with the output that surprised you the most.', 2, 1, null, '{}'::jsonb),
    ('video', 'Prompting', null, 3, 0, 'Prompting', '{}'::jsonb),
    ('use_example', 'Task', 'Take a Project you''ve already built (or build a new one) and use the CRISPE framework in the instructions.
Run a chat here again and check the output.
Submit the Project as an example of one using a framework.', 3, 1, null, '{}'::jsonb),
    ('session', 'Live session 1', null, 3, 2, null, '{"slots":2}'::jsonb),
    ('video', 'Projects', null, 4, 0, 'Projects', '{}'::jsonb),
    ('use_example', 'Task', 'Pick one task you repeat and build a Project for it, giving it:
- custom instructions
- 2-3 knowledge files
- access with anyone else who could use it
Then test it and check the output.
If the output is exactly what you need, it''s good to go. If not, the instructions might be missing something - check and add in whatever is required.
Submit the link to the Project below.', 4, 1, null, '{}'::jsonb),
    ('video', 'Connectors & MCP', null, 5, 0, 'Connectors & MCP', '{}'::jsonb),
    ('use_example', 'Task', 'Go to Customize > Connectors and enable the tools you use daily.
Click on a specific connector and check the permissions that it allows by default. If you need additional functionality or are unsure what functionality is safe to enable for a specific connector, let Haseeb know.
Disconnect anything you added to have a look at and are not going to use.', 5, 1, null, '{}'::jsonb),
    ('quiz', 'Week 1 Quiz', null, 5, 3, null, '{"pass_mark":8,"question_count":10,"summative":false,"questions":[{"day":1,"question":"In an ordinary Chat, with web search turned off and no Connectors enabled, you ask Claude for the current list price of a product line. It answers with a precise figure, to the penny. Where did that number come from?","options":["It looked the price up and reported back what it found","It calculated it from related figures that it does hold","It predicted a plausible figure from patterns in its training data","It reported the last value it saw, so it is current unless the price moved","It inferred it from your earlier messages in this Chat"],"correct":2,"explanation":"Nothing was looked up. Claude predicts what comes next, so a figure arrives in whatever shape the surrounding sentence calls for, and two decimal places is a writing habit rather than evidence. When the number is right, that is training data agreeing with reality. Anything that moves needs a Connector or a source you open yourself."},{"day":1,"question":"Two hours into a long Chat, Claude starts breaking a formatting rule you set at the very beginning and had been following all along. What is the likeliest cause?","options":["It has decided your later instructions override the earlier one","The Chat has outgrown what Claude can hold in view at once","Output quality degrades over a long session, so it needs restarting","Its training data disagrees with the rule that you set","The rule was not stated firmly enough for it to stick"],"correct":1,"explanation":"Everything Claude can see has to fit in one window, and a long Chat pushes the beginning of it out of range. Restating the rule, or carrying the essentials into a fresh Chat, fixes it. Saying it more firmly does not, because the instruction is not being defied, it is not being seen."},{"day":2,"question":"Which of these is the weakest candidate for handing to Claude?","options":["Drafting the first version of a recurring internal update","Summarising a supplier contract you will read properly afterwards","Signing off the final numbers in the month-end pack","Reformatting a messy stock export into a consistent structure","Drafting a tender rejection letter that is reviewed before it goes"],"correct":2,"explanation":"Drafting, summarising and reformatting are where Claude earns its keep, and an awkward subject does not change that while the draft is reviewed before it goes. Signing off is the one that cannot move, because accountability is not a task. Use Claude to prepare what informs the decision rather than to make it."},{"day":2,"question":"Two colleagues use Claude on similar work. One handed over a whole process end to end and is disappointed. The other handed over only the drafting and is not. What explains the gap?","options":["The second colleague simply writes better prompts than the first","Judgement and accountability do not transfer, but drafting does","The first colleague is working on genuinely more complex material","The second colleague has been using the tool for a lot longer","The first colleague needs a Project and the second already has one"],"correct":1,"explanation":"Complexity is not the dividing line and neither is fluency with the tool. What transfers is the blank page and the repetitive middle. What does not is deciding and owning the result, so a process handed over whole always disappoints at the point where somebody has to be answerable. Prompting and Projects both help, and neither moves that line."},{"day":3,"question":"A prompt in a Chat returns content that is accurate and complete, but it reads like a different company wrote it. Which part of CRISPE is missing?","options":["Context","Instructions","Parameters","Role","Style"],"correct":4,"explanation":"Style is tone, register and voice. The content being right tells you Context and Instructions did their job. Role changes the expertise Claude writes from rather than the voice it writes in, and Parameters constrain length, format and what to leave out. When output is correct but reads wrong, Style is the gap."},{"day":3,"question":"You have to write this month''s report in exactly the same shape as last month''s: the same sections, in the same order, with the same kind of summary at the top. Which part of CRISPE does most of the work?","options":["Instructions, listing out every formatting rule you can think of first","Example, pasting last month''s report so it can copy the shape","Parameters, specifying the length and the number of sections","Context, explaining who reads the report and what they need from it","Role, so it writes as the person who produced the original one"],"correct":1,"explanation":"One example carries more specification than a page of rules, and it removes the ambiguity a description always leaves behind. Parameters and Instructions can approximate the shape and never the phrasing. Role and Context change how Claude thinks rather than what it hands you."},{"day":4,"question":"Every week you paste the same background into a new Chat before you can ask your real question: your team''s terminology, the format you need and the standing constraints. What fixes that properly?","options":["Keep the preamble in a note and paste it at the top of each Chat","Write one much longer prompt so that nothing important gets missed","Ask Claude to remember the background at the end of each Chat","Put the background and reference files in a Project","Add a Connector to the systems that background describes"],"correct":3,"explanation":"A Project holds standing context, so every Chat inside it starts briefed and nobody maintains a preamble by hand. A pasted note drifts the moment the format changes and a longer prompt moves the repetition rather than removing it. A Connector fetches live state, which is a different problem from standing background."},{"day":4,"question":"A Project you built answers the exact question you built it around very well, and anything slightly different badly. What does that tell you?","options":["The knowledge files you gave it are too small to generalise from","Projects are built for one job, so varied work belongs in a Chat","The instructions describe one task rather than how you work","You need a separate Project for each question you want to ask","Requests have to be phrased the way you phrased the original one"],"correct":2,"explanation":"A Project that only answers its founding question is a saved prompt with extra steps. Standing context is the method, the vocabulary and the constraints, and those carry across requests. Splitting it per question multiplies what you maintain and teaches the same lesson again a month later."},{"day":5,"question":"Several times a day you copy the same figures out of the same system and paste them into a Chat. What is that a signal for?","options":["A Connector, so Claude can reach the system itself","A longer prompt that carries more of the background with it","A Project holding the most recent export of those figures","Nothing, copy and paste is perfectly fine at that volume","A Scheduled Task that pastes the figures in for you each morning"],"correct":0,"explanation":"Repetitive copy and paste is the clearest signal that a Connector pays for itself. A Project holds context that changes slowly, and an export dropped into one is stale the moment it is saved. A schedule automates the ferrying rather than removing it, which leaves you the same stale figures on a timer."},{"day":5,"question":"A colleague worries that connecting a system to Claude will expose data they are not allowed to see. Which of the following is correct?","options":["They are right, a Connector reads the system and bypasses its permissions","Connectors are limited to data that the system already publishes openly","It depends entirely on which Connector and which system it is","It is safe provided they enable only the permissions the job needs","A Connector works within the access they already have"],"correct":4,"explanation":"A Connector is a route rather than a promotion, so their existing access is the ceiling. Checking the permissions a Connector allows by default is good practice and the day''s task asks for it, and it is still not what makes the answer safe. Worth being clear on in a regulated business, because the fear is common and it stops people using something useful."}]}'::jsonb),
    ('video', 'Skills', null, 6, 0, 'Skills', '{}'::jsonb),
    ('use_example', 'Task', 'Pick one thing you explain to Claude repeatedly (e.g. how a report should be laid out, how a summary should be structured, the checks a piece of work has to pass before you send it).
Go to Customize > Skills and build a Skill for it, letting the built-in skill-creator draft it from your description rather than writing it from scratch. Give it:
- a description saying when to use it
- one task only
- the method it should complete the task using
Then test it by starting a fresh chat and asking to complete the task required without naming the skill.
Try over a few runs with different wording.
If the skill fires, then everything is working. If not, the description is likely too vague or ambiguous. Fix this and try again.
Submit the link to the chat where your Skill fired on its own.', 6, 1, null, '{}'::jsonb),
    ('video', 'Scheduled Tasks', null, 7, 0, 'Scheduled Tasks', '{}'::jsonb),
    ('use_example', 'Task', 'Go to Scheduled in the sidebar and use New task to set up one job you do on a rhythm, with a frequency and a time you will be away from your desk.
Click Run now once and choose always allow on the permission prompts you recognise, or a scheduled run stalls waiting for you.
Do not tie it to a folder on your computer: those only run when you are there. Use your Connectors and files saved to your Claude account.
Submit the link to its first completed run.', 7, 1, null, '{}'::jsonb),
    ('video', 'Artifacts', null, 8, 0, 'Artifacts', '{}'::jsonb),
    ('use_example', 'Task', 'Pick something you rebuild most weeks - a status update, a meeting-prep sheet, a checklist - and ask Claude to make it as an Artifact you can reuse.
Change it once in plain English rather than keeping the first draft. Every version is kept, so you can go back. If Claude answers in the chat instead of opening a panel, check Settings > Capabilities for Code execution and file creation, and ask Haseeb if it is not yours to change.
Share it. On our Team plan a shared Artifact opens only for people signed in with their Phlo account, so if it has to reach anyone outside, ask Haseeb rather than working round it.
Made-up numbers only in anything you share, and keep logins and keys out of it.
Submit the link to your Artifact.', 8, 1, null, '{}'::jsonb),
    ('session', 'Live session 2', null, 8, 2, null, '{"slots":2}'::jsonb),
    ('video', 'Cowork', null, 9, 0, 'Cowork', '{}'::jsonb),
    ('use_example', 'Task', 'Pick a boring job you keep putting off (e.g. merging a few documents into one summary, checking two lists against each other, tidying up and renaming a group of files). Put the files Cowork needs into one folder - don''t add anything else.
Open Cowork in the desktop app, point it to that folder and tell it the whole task in one sentence. Then set it to "Skip all approvals" to allow it to do the work without asking for approvals.
Cowork works on your real files, so keep this folder small and make sure there''s nothing unrelated or confidential in it.
Submit the link to the final output.', 9, 1, null, '{}'::jsonb),
    ('video', 'Claude Design', null, 10, 0, 'Claude Design', '{}'::jsonb),
    ('use_example', 'Task', 'Describe one screen or document you wish already existed: a landing page, a settings screen, a pitch deck, a one-pager that would make an idea look finished.
Open Claude Design at claude.ai/design, or from the sidebar in the desktop app. Make it there, then refine it once in plain English rather than taking the first version. A strong first draft that a person then shapes is the whole method.
Export what you end up with - the Export button offers PowerPoint, PDF and a standalone page, among others.
Two honest caveats. It is a research preview, so it is rougher than the rest of the tools here and what comes out is a draft rather than a finished brand. And keep confidential designs, patient-facing material and private code out of it.
Submit the link to the design, or to the file you exported.', 10, 1, null, '{}'::jsonb),
    ('quiz', 'Week 2 Quiz', null, 10, 3, null, '{"pass_mark":8,"question_count":10,"summative":false,"questions":[{"day":6,"question":"You have a reliable method for a recurring task and two colleagues want to use it. What makes a Skill the right home for it, rather than a Project or a saved prompt?","options":["They turn it on once, then it fires by itself","It stores the documents the task needs alongside the method","It runs to a timetable, whether or not the job came up","It gives Claude access to the system that the task depends on","It keeps the method private to the colleagues you name on it"],"correct":0,"explanation":"A Skill packages how you do something so other people''s Chats can reach it: a colleague switches it on once, and from then on its description is what makes it fire without being named. Documents are a Project, a timetable is a Scheduled Task and system access is a Connector. Choosing the wrong container is what makes simple work feel like overhead."},{"day":6,"question":"You built a Skill and it never fires unless you name it explicitly in the Chat. What is almost always wrong?","options":["The instructions inside the Skill have grown too long to parse","It has to be shared with your team before it will trigger at all","The task is too narrow for a Skill to be the right container","Its description is too vague to match what people actually ask","Skills only fire automatically for the person who created them"],"correct":3,"explanation":"The description is the trigger. Use this when formatting a monthly performance report fires when it should, and helps with reports never fires at all. Sharing changes who can reach a Skill rather than whether it triggers, and a narrow task is exactly what a Skill wants."},{"day":7,"question":"From Scheduled in the sidebar you set a task to run the stock summary at 07:00 each Monday. You reach your desk at 08:30 and your laptop was shut overnight. What happens?","options":["It waits until you open the laptop, so the result arrives late","It ran at 07:00 without your machine, and the result is waiting","It is skipped entirely and runs again the following Monday","It fails, and you get a notification telling you that it failed","It ran at 07:00 but could not reach your Connectors while you were away"],"correct":1,"explanation":"Scheduled runs happen on Anthropic''s servers, so they keep their cadence with your computer asleep and the desktop app shut, and your connected tools go with them. Nothing is deferred, skipped or failed. The one thing that does still need your machine is a task reaching files or apps on it, which is why a schedule is built on your Connectors and the files saved to your Claude account rather than on a folder."},{"day":7,"question":"A Scheduled Task you set up three weeks ago still runs, but you now rewrite most of its output before you use it. What should you do?","options":["Leave it running, since it is still saving you time overall","Delete it and go back to doing the whole task by hand again","Run it more often so that its output stays closer to current","Keep it, and log the saving as the full time the task once took","Fold what you keep rewriting back in, or retire the task"],"correct":4,"explanation":"Heavy editing means the task and the real work have drifted apart, and what you keep rewriting is the specification. Running it more often just produces more to correct. Logging the old full cost is how a time saving becomes a number nobody believes, because the saving is what the job costs now against what it cost before."},{"day":8,"question":"You have asked Claude for a checklist your team will use every week. Why ask for it as an Artifact rather than as text in the Chat?","options":["Artifacts are generated faster than the same answer in a Chat","Claude is more accurate when it writes into an Artifact","You get something you can edit, version and share on its own","It uses fewer messages, so you get more out of your limits","Anyone you share it with can edit your copy of it directly"],"correct":2,"explanation":"An Artifact is the output as an object rather than as Chat scrollback: refined in place, every version kept, and shareable to people who need the checklist rather than the conversation behind it. Speed and accuracy are unchanged. Sharing lets other people open and use it, which is not the same as handing them edit rights on yours."},{"day":8,"question":"You have built a margin calculator as an Artifact in Claude and you are about to share the link so your team can use it. This quarter''s real supplier prices are typed into it. What has to happen first?","options":["Share it, then message the team asking them not to forward the link","Nothing, a shared Artifact is reachable only by the people you send it to","Swap the real prices for made-up ones before you share it","Leave the real prices in and write a confidentiality note at the top of the page","Share it with only the two colleagues who actually need it"],"correct":2,"explanation":"Sharing is the step that changes who can see something: on our plan a shared Artifact opens for anyone at Phlo with the link, not just the people you had in mind, and it carries the files attached to the conversation that built it along with it. Plenty of them have no business seeing supplier pricing, which is what makes live figures the wrong thing to leave in. A confidentiality note changes nothing about who can open the page, asking colleagues not to forward a link is not a control, and a share cannot be narrowed to two named people: the choice is everyone in the organisation or nobody."},{"day":9,"question":"Which of these is the strongest candidate for Cowork rather than an ordinary Chat?","options":["A question you need a single short answer to before this afternoon","Drafting an email to a supplier about a late delivery","Deciding which of two suppliers your team should move to","Working through a live document with a colleague at the same time","Merging six monthly reports into one summary and filing them"],"correct":4,"explanation":"Cowork earns its keep on assembly across many files on your own machine: work that is tedious rather than difficult, and that ends in files rather than in an answer. A short question and a draft are ordinary Chat, deciding is yours to own, and a Cowork session cannot be worked on by two people at once, so anything live and shared belongs elsewhere."},{"day":9,"question":"You are handing a job to Cowork in the desktop app and you have skipped the permission prompts so it can work without stopping to ask. What is keeping it away from files it has no business opening?","options":["The folder you pointed it at, and whatever you chose to put in it","Claude''s judgement about which of your files the task actually needs","The one-sentence brief, which tells it what it is allowed to open","The desktop app, which reaches your Claude account rather than your disk","Nothing much, so read every file it touched once the run has finished"],"correct":0,"explanation":"Skipping the prompts is what makes the folder the control. There is no per-step approval left, so the only thing between Cowork and a file is whether you put that file in scope before the run started. Claude cannot know which of your documents are commercially sensitive. A brief describes the goal rather than granting access, and the desktop app is the route to your disk rather than a limit on it: on our plan the run itself happens on Anthropic''s servers and reaches your files through that app, for the folders you connected and no others. Reading afterwards is worth doing but it is not a boundary, because by then it has opened whatever was there."},{"day":10,"question":"You need a pitch deck for Monday and you want to shape the layout before it goes out. Where does Claude Design earn its place over an ordinary Chat?","options":["It writes the words on each slide more accurately than a Chat does","It signs the deck off, so nobody else has to review what it made","It keeps the deck''s source documents attached for the next revision","You shape the layout on a canvas and export the result as a PPTX","It is the only surface at Phlo that can read a PowerPoint file"],"correct":3,"explanation":"The gain is a canvas plus a real export. You adjust spacing, colour and layout directly, or ask for changes in plain English, and the Export button gives you PowerPoint, PDF or a standalone page. A Chat can draft the words but hands them back as text for you to reassemble. Keeping source documents for next time is what a Project is for. Nothing here removes the human review, and a Chat reads a PowerPoint file perfectly well."},{"day":10,"question":"Which of the following is the poorest fit for Claude Design as it stands today?","options":["An internal one-pager explaining a process change to your team","A rough settings screen, made to get a conversation started","A patient-facing leaflet going out under Phlo''s brand","A slide for Monday''s team meeting that you will talk over","A layout you want to react to before committing real time to it"],"correct":2,"explanation":"Two things make it the wrong fit. It is a research preview, so what comes out is a draft rather than a finished brand, and patient-facing material has to meet a standard a draft is not aiming at. Confidential designs and private code stay out for the same reason. Internal drafts, rough screens and something to react to are exactly the work it is for."}]}'::jsonb),
    ('video', 'Research, Memory & files out', null, 11, 0, 'Research, Memory & files out', '{}'::jsonb),
    ('use_example', 'Task', 'Pick something you would normally lose an afternoon to: a comparison, a supplier or market scan, a written summary that means reading several sources first.
Run it with Research rather than a normal chat. It searches, reads and cross-references many sources and then writes the whole thing up, and it runs in the background - so start it and go and do something else.
Then ask for the result as a file rather than as chat text: a document, a spreadsheet or a deck. Reassembling a finished thing out of a chat by hand is the work you are meant to be stopping.
While you are in Settings, turn Memory on and read what it already holds about you. It saves you the re-briefing every time; it does not make anything more accurate, so nothing about the checking habit changes.
Submit the link to the Research chat, or to the file if it lives somewhere shareable.', 11, 1, null, '{}'::jsonb),
    ('video', 'Reverse Prompting', null, 12, 0, 'Reverse Prompting', '{}'::jsonb),
    ('use_example', 'Task', 'Find a prompt that is not working - one you have reworded twice and it still comes back the wrong shape.
Stop rewording it. Turn the questioning round instead: ask Claude what it needs from you in order to do this properly, and then answer its questions.
The questions are the point. What it asks about is almost always context you did not realise you were assuming, and that is the real problem rather than your phrasing.
Run the job again with what came out of the interview, and compare it against the version you were stuck on.
Learn the signal while you are here. One poor answer is normal and a follow-up is just conversation. The same wrong shape three times means the misunderstanding is upstream of the wording, and no rewrite will reach it.
Submit the link to the chat where you let it interview you.', 12, 1, null, '{}'::jsonb),
    ('video', 'Dispatch + Plugins', null, 13, 0, 'Dispatch + Plugins', '{}'::jsonb),
    ('use_example', 'Task', 'Find the thing Claude keeps failing at because it cannot reach or cannot do something, rather than because you asked badly.
Learn to tell those two apart, because the diagnosis is where the time goes. ''It misunderstood me'' is a prompt problem and better wording fixes it. ''It cannot get to that'' is a capability problem and no rewrite will ever reach it.
Then close the gap rather than rewriting the prompt: add the Plugin that gives Claude the thing it was missing, and run the same job again.
Prompting changes how well you use what is already there. Plugins change what is there.
Submit the link to the job you got working.', 13, 1, null, '{}'::jsonb),
    ('session', 'Live session 3', null, 13, 2, null, '{"slots":2}'::jsonb),
    ('submission_slot', 'Capstone', null, 13, 4, null, '{"kind":"capstone","visibility":"cohort"}'::jsonb),
    ('video', 'Claude everywhere', null, 14, 0, 'Claude everywhere', '{}'::jsonb),
    ('use_example', 'Task', 'Think about where you actually spend the day: a spreadsheet, your inbox, Slack, a browser tab, a document. Claude is available inside most of it.
Install it in the one you live in most. Then do the small job you would never normally open Claude for - the two-minute rewrite, the quick summary, the formula you would have looked up.
That is the point of today. The barrier was never capability, it was friction: stopping, switching app, re-explaining the context and pasting the answer back is enough to make anyone skip a small job. Small jobs are where most of the saving quietly adds up.
Submit the link to the thing you did without leaving the tool you were already in.', 14, 1, null, '{}'::jsonb),
    ('video', 'Choosing the right tool + measuring time saved', null, 15, 0, 'Choosing the right tool + measuring time saved', '{}'::jsonb),
    ('use_example', 'Task', 'List the jobs you moved to Claude over the three weeks, with what each one used to take and what it takes now. If you have kept a Time-Back Log this is that list already; if you have not, build it now.
Then time one of them properly rather than estimating it. Pick the job you are claiming the biggest saving on, run it end to end with the clock going, and write the real number down next to your guess.
That step is the point of today. An estimated saving is the one figure nobody outside this programme has any reason to believe, and the gap between your guess and the clock is usually the most useful thing on the page.
Then choose the container for that job, because picking the wrong one is what people still get wrong long after the features are familiar:
- a Chat for a one-off
- a Project when the background is the same every time
- a Skill when it is a method colleagues should reuse
- a Scheduled Task when it runs on a rhythm
- Cowork when it is assembly across your own files
- an Artifact when the output is a thing your team will open again
If the job you have run in an ordinary Chat all fortnight belongs in one of the other five, move it now.
Submit the link to your log.', 15, 1, null, '{}'::jsonb),
    ('quiz', 'Week 3 Quiz', null, 15, 3, null, '{"pass_mark":8,"question_count":10,"summative":true,"questions":[{"day":11,"question":"You need a written comparison of three couriers'' terms, ready to send on. Which approach uses what Claude is actually good at?","options":["Ask for the comparison, then copy the answer out of the Chat by hand","Ask three separate questions and stitch the answers together yourself","Ask for bullet points in a Chat and write the document up yourself","Ask Research to compare all three and hand back a finished file","Ask for the comparison, paste it into a document and format it"],"correct":3,"explanation":"Research searches, reads and cross-references, then hands back the finished file rather than leaving you to reassemble a document out of Chat text, and it runs in the background while you do something else. Every other option ends with you doing the part the tool would have done."},{"day":11,"question":"You turn Memory on and Claude starts carrying your role, your team''s terminology and your usual formats between Chats. What does that change?","options":["Factual answers get more reliable, because it knows your situation","You stop re-briefing it at the start of every Chat, nothing more","It can now reach your company systems without needing a Connector","Your Chats become visible to colleagues who share the same memory","It stops inventing detail on topics it now holds context about"],"correct":1,"explanation":"Memory removes the re-briefing. It does not turn a prediction into a lookup, so the checking habit is untouched, and knowing your team''s vocabulary does not stop Claude inventing a figure. It grants no system access, which is what a Connector is for, and it shares nothing with anyone."},{"day":12,"question":"You have reworded a prompt three times and the answer keeps coming back the same shape of wrong. What does the programme tell you to do next?","options":["Reword it once more, being precise about the format you want","Start a fresh Chat, on the basis that this one is confused","Accept that the job is outside what the tool can do for you","Ask Claude to interview you about what it needs, then answer","Add more context in bulk until the answer eventually shifts"],"correct":3,"explanation":"The same wrong shape repeating means the gap is in what you have not said rather than in how you said it, and no rewrite reaches that. Letting Claude ask what it needs surfaces the context you were assuming without noticing. One poor answer is normal and a follow-up is just conversation - it is the repetition that is the signal. A fresh Chat and bulk context are the same guess made again."},{"day":13,"question":"Claude keeps failing at a job you have given it. How do you tell a prompting problem from a capability problem?","options":["It misunderstood you is prompting; it cannot reach that is capability","A slow job means it is straining against a limit, so capability","A confident wrong answer means a capability gap rather than wording","Capability problems always show an error, so anything else is wording","It rarely matters, because better prompting helps in both cases"],"correct":0,"explanation":"Prompting changes how well you use what is already there. Plugins change what is there. The diagnosis is where the time goes, because rewriting a prompt against a capability gap can absorb an afternoon and never work. Capability gaps rarely announce themselves, and a confident wrong answer is a verification problem rather than a capability one."},{"day":14,"question":"You spend most of your day in Excel and Slack, and Claude is available inside both. What follows from that?","options":["You should still work in the Claude app and paste results across","The in-tool versions are weaker, so avoid them for real work","It only matters for people who work mostly in documents","It matters most for long tasks, which are worth setting up for","Small jobs stop being worth skipping, because the switch is gone"],"correct":4,"explanation":"The barrier was rarely capability, it was friction. Stopping, switching app, re-explaining the context and pasting the answer back is enough to make anyone skip a two-minute job, and small jobs are where most of the saving quietly adds up. Long tasks were always worth the switch, so they are not where this changes anything."},{"day":15,"question":"You are totalling up what the three weeks saved you. For the job you claim the biggest saving on, the before figure and the after figure are both ones you remembered. What is the problem?","options":["Nothing is wrong, you ran the job both ways so both figures are yours","The before figure will be inflated, because slow work feels longer","Neither figure was measured, so the saving is a guess with a decimal","The saving belongs to the team rather than to you, so it double counts","Three weeks is too short a window to draw any saving from at all"],"correct":2,"explanation":"Remembered numbers drift in the direction you want them to go, and the before figure drifts furthest because the old way is the one you resented. One timed run is worth more than fifteen estimates. It is also the only version of the figure that survives somebody outside the programme asking how you arrived at it, which is the question this whole exercise is preparing you for."},{"day":15,"question":"You have halved the time your weekly report takes by drafting it in a Chat. You now spend ten minutes checking figures you used to take straight from the system. How should that land in your total?","options":["Leave it out, checking is overhead rather than part of the job","Subtract it, because the job is not finished until it is checked","Count it separately, as a cost of Claude rather than a cost of the job","Ignore it, the checking tails off once the drafting has earned trust","Halve it, since you would have checked some of those figures anyway"],"correct":1,"explanation":"The number worth having is the one you could defend to somebody outside the programme, and that is the job end to end rather than the drafting step on its own. Checking is not overhead bolted onto the work, it is the part that makes the output usable. A total that quietly drops it is the kind of figure that falls apart the first time anyone asks how it was built."},{"day":3,"question":"A prompt keeps producing output that is accurate but consistently the wrong length and format for where it has to go. Which part of CRISPE do you reach for?","options":["Context","Role","Instructions","Parameters","Example"],"correct":3,"explanation":"Parameters are the constraints: length, format, structure and what to leave out. Context and Role shape what Claude knows and how it thinks, and Instructions say what to do rather than what shape to do it in. An Example would work too, and it costs you a document to paste; when the content is already right, Parameters is the smaller lever."},{"day":5,"question":"Your team has a Project full of reference documents and a Connector to the system those documents describe. When does the Connector earn its keep?","options":["When you need what the system says now, not what it said then","Always, because a Connector is the more capable feature of the two","Only once the Project grows too large to search reliably","Never, since the two of them do the same job by other means","When the documents in the Project are more than a month old"],"correct":0,"explanation":"A Project holds standing context that changes slowly and a Connector fetches live state. Reference material belongs in the Project and anything that moves belongs behind the Connector, whatever its age: a document goes stale when the system changes rather than after a set period. Treating a stored document as current is a quiet source of wrong answers."},{"day":7,"question":"You have a recurring task, a one-off question, a method colleagues should reuse and a system Claude cannot reach. Which mapping is right?","options":["Skill, Scheduled Task, Project, Connector","Project, Skill, Connector, Plugin","Scheduled Task, Chat, Skill, Connector","Connector, Artifact, Scheduled Task, Skill","Scheduled Task, Chat, Project, Connector"],"correct":2,"explanation":"Recurring and predictable is a Scheduled Task, a one-off just needs a Chat, a repeatable method other people can run is a Skill and reaching a system is a Connector. The near miss puts a Project in the third slot: a Project holds standing context for your own Chats rather than packaging a method somebody else''s Chat can trigger. Choosing the wrong container is what makes simple work feel like overhead."}]}'::jsonb),
    ('submission_slot', 'Work sample (after)', null, 15, 4, null, '{"kind":"work_sample_post","visibility":"private"}'::jsonb),
    ('questionnaire_post', 'Your AI Score - see what three weeks did', null, 15, 5, null, '{}'::jsonb)
)
insert into public.programme_track_items
  (track_id, type, title, description, day_index, sort_order, learn_video_id, config_json)
select t.id, s.type, s.title, s.description, s.day_index, s.sort_order,
       (select v.id from public.learn_videos v where lower(v.title) = lower(s.learn_video_title) limit 1),
       s.config_json
  from spec s cross join track t
 where not exists (
   select 1 from public.programme_track_items i
    where i.track_id = t.id and i.day_index = s.day_index and i.sort_order = s.sort_order
 );

-- Sync titles and descriptions from the spec. These are seed-owned: admins
-- rename Learn videos, not track days, so overwriting is safe and it means
-- re-running the seed actually applies a wording change to an existing track.
update public.programme_track_items i
   set title = s.title, description = s.description
  from (values
    (0, 0, 'Your AI Score - 3-minute check-in', 'A quick self-assessment. It sets your starting point and unlocks the programme.'),
    (1, 0, 'What is AI and how does it work?', 'Prediction rather than lookup, the context window, training cutoff vs live data, the three failure sources and Time-Back Log setup.'),
    (1, 1, 'Task', 'Sign in to Claude with your Phlo email, install the desktop app, then run one real task from this week through it.
Submit the link to that task.'),
    (1, 4, 'Work sample (before)', null),
    (2, 0, 'When to use AI and when not to', null),
    (2, 1, 'Task', 'Pick three jobs from this week:
- one you are confident Claude will do well
- one you are confident Claude will not do well
- one where you are not sure whether it will produce the correct output
Before you open Claude, predict each outcome and rate it Certain, Fairly confident or Guessing.
Run all three separately, including the one you expect to fail, and compare the output to your predictions.
If something worked that you expected not to, that is something to delegate to Claude immediately. Something that gave an incorrect output is one to be cautious about and double-check.
If Claude did not produce the output you wanted for a specific task, try again. Add more context, add an example document, or split it into two steps, and see whether that helps.
Submit the link to one of these, preferably the one with the output that surprised you the most.'),
    (3, 0, 'Prompting', null),
    (3, 1, 'Task', 'Take a Project you''ve already built (or build a new one) and use the CRISPE framework in the instructions.
Run a chat here again and check the output.
Submit the Project as an example of one using a framework.'),
    (3, 2, 'Live session 1', null),
    (4, 0, 'Projects', null),
    (4, 1, 'Task', 'Pick one task you repeat and build a Project for it, giving it:
- custom instructions
- 2-3 knowledge files
- access with anyone else who could use it
Then test it and check the output.
If the output is exactly what you need, it''s good to go. If not, the instructions might be missing something - check and add in whatever is required.
Submit the link to the Project below.'),
    (5, 0, 'Connectors & MCP', null),
    (5, 1, 'Task', 'Go to Customize > Connectors and enable the tools you use daily.
Click on a specific connector and check the permissions that it allows by default. If you need additional functionality or are unsure what functionality is safe to enable for a specific connector, let Haseeb know.
Disconnect anything you added to have a look at and are not going to use.'),
    (5, 3, 'Week 1 Quiz', null),
    (6, 0, 'Skills', null),
    (6, 1, 'Task', 'Pick one thing you explain to Claude repeatedly (e.g. how a report should be laid out, how a summary should be structured, the checks a piece of work has to pass before you send it).
Go to Customize > Skills and build a Skill for it, letting the built-in skill-creator draft it from your description rather than writing it from scratch. Give it:
- a description saying when to use it
- one task only
- the method it should complete the task using
Then test it by starting a fresh chat and asking to complete the task required without naming the skill.
Try over a few runs with different wording.
If the skill fires, then everything is working. If not, the description is likely too vague or ambiguous. Fix this and try again.
Submit the link to the chat where your Skill fired on its own.'),
    (7, 0, 'Scheduled Tasks', null),
    (7, 1, 'Task', 'Go to Scheduled in the sidebar and use New task to set up one job you do on a rhythm, with a frequency and a time you will be away from your desk.
Click Run now once and choose always allow on the permission prompts you recognise, or a scheduled run stalls waiting for you.
Do not tie it to a folder on your computer: those only run when you are there. Use your Connectors and files saved to your Claude account.
Submit the link to its first completed run.'),
    (8, 0, 'Artifacts', null),
    (8, 1, 'Task', 'Pick something you rebuild most weeks - a status update, a meeting-prep sheet, a checklist - and ask Claude to make it as an Artifact you can reuse.
Change it once in plain English rather than keeping the first draft. Every version is kept, so you can go back. If Claude answers in the chat instead of opening a panel, check Settings > Capabilities for Code execution and file creation, and ask Haseeb if it is not yours to change.
Share it. On our Team plan a shared Artifact opens only for people signed in with their Phlo account, so if it has to reach anyone outside, ask Haseeb rather than working round it.
Made-up numbers only in anything you share, and keep logins and keys out of it.
Submit the link to your Artifact.'),
    (8, 2, 'Live session 2', null),
    (9, 0, 'Cowork', null),
    (9, 1, 'Task', 'Pick a boring job you keep putting off (e.g. merging a few documents into one summary, checking two lists against each other, tidying up and renaming a group of files). Put the files Cowork needs into one folder - don''t add anything else.
Open Cowork in the desktop app, point it to that folder and tell it the whole task in one sentence. Then set it to "Skip all approvals" to allow it to do the work without asking for approvals.
Cowork works on your real files, so keep this folder small and make sure there''s nothing unrelated or confidential in it.
Submit the link to the final output.'),
    (10, 0, 'Claude Design', null),
    (10, 1, 'Task', 'Describe one screen or document you wish already existed: a landing page, a settings screen, a pitch deck, a one-pager that would make an idea look finished.
Open Claude Design at claude.ai/design, or from the sidebar in the desktop app. Make it there, then refine it once in plain English rather than taking the first version. A strong first draft that a person then shapes is the whole method.
Export what you end up with - the Export button offers PowerPoint, PDF and a standalone page, among others.
Two honest caveats. It is a research preview, so it is rougher than the rest of the tools here and what comes out is a draft rather than a finished brand. And keep confidential designs, patient-facing material and private code out of it.
Submit the link to the design, or to the file you exported.'),
    (10, 3, 'Week 2 Quiz', null),
    (11, 0, 'Research, Memory & files out', null),
    (11, 1, 'Task', 'Pick something you would normally lose an afternoon to: a comparison, a supplier or market scan, a written summary that means reading several sources first.
Run it with Research rather than a normal chat. It searches, reads and cross-references many sources and then writes the whole thing up, and it runs in the background - so start it and go and do something else.
Then ask for the result as a file rather than as chat text: a document, a spreadsheet or a deck. Reassembling a finished thing out of a chat by hand is the work you are meant to be stopping.
While you are in Settings, turn Memory on and read what it already holds about you. It saves you the re-briefing every time; it does not make anything more accurate, so nothing about the checking habit changes.
Submit the link to the Research chat, or to the file if it lives somewhere shareable.'),
    (12, 0, 'Reverse Prompting', null),
    (12, 1, 'Task', 'Find a prompt that is not working - one you have reworded twice and it still comes back the wrong shape.
Stop rewording it. Turn the questioning round instead: ask Claude what it needs from you in order to do this properly, and then answer its questions.
The questions are the point. What it asks about is almost always context you did not realise you were assuming, and that is the real problem rather than your phrasing.
Run the job again with what came out of the interview, and compare it against the version you were stuck on.
Learn the signal while you are here. One poor answer is normal and a follow-up is just conversation. The same wrong shape three times means the misunderstanding is upstream of the wording, and no rewrite will reach it.
Submit the link to the chat where you let it interview you.'),
    (13, 0, 'Dispatch + Plugins', null),
    (13, 1, 'Task', 'Find the thing Claude keeps failing at because it cannot reach or cannot do something, rather than because you asked badly.
Learn to tell those two apart, because the diagnosis is where the time goes. ''It misunderstood me'' is a prompt problem and better wording fixes it. ''It cannot get to that'' is a capability problem and no rewrite will ever reach it.
Then close the gap rather than rewriting the prompt: add the Plugin that gives Claude the thing it was missing, and run the same job again.
Prompting changes how well you use what is already there. Plugins change what is there.
Submit the link to the job you got working.'),
    (13, 2, 'Live session 3', null),
    (13, 4, 'Capstone', null),
    (14, 0, 'Claude everywhere', null),
    (14, 1, 'Task', 'Think about where you actually spend the day: a spreadsheet, your inbox, Slack, a browser tab, a document. Claude is available inside most of it.
Install it in the one you live in most. Then do the small job you would never normally open Claude for - the two-minute rewrite, the quick summary, the formula you would have looked up.
That is the point of today. The barrier was never capability, it was friction: stopping, switching app, re-explaining the context and pasting the answer back is enough to make anyone skip a small job. Small jobs are where most of the saving quietly adds up.
Submit the link to the thing you did without leaving the tool you were already in.'),
    (15, 0, 'Choosing the right tool + measuring time saved', null),
    (15, 1, 'Task', 'List the jobs you moved to Claude over the three weeks, with what each one used to take and what it takes now. If you have kept a Time-Back Log this is that list already; if you have not, build it now.
Then time one of them properly rather than estimating it. Pick the job you are claiming the biggest saving on, run it end to end with the clock going, and write the real number down next to your guess.
That step is the point of today. An estimated saving is the one figure nobody outside this programme has any reason to believe, and the gap between your guess and the clock is usually the most useful thing on the page.
Then choose the container for that job, because picking the wrong one is what people still get wrong long after the features are familiar:
- a Chat for a one-off
- a Project when the background is the same every time
- a Skill when it is a method colleagues should reuse
- a Scheduled Task when it runs on a rhythm
- Cowork when it is assembly across your own files
- an Artifact when the output is a thing your team will open again
If the job you have run in an ordinary Chat all fortnight belongs in one of the other five, move it now.
Submit the link to your log.'),
    (15, 3, 'Week 3 Quiz', null),
    (15, 4, 'Work sample (after)', null),
    (15, 5, 'Your AI Score - see what three weeks did', null)
  ) as s(day_index, sort_order, title, description)
 where i.day_index = s.day_index and i.sort_order = s.sort_order
   and i.track_id = (select id from public.programme_tracks where slug = 'core-programme')
   and (i.title is distinct from s.title or i.description is distinct from s.description);

-- Sync quiz config from the spec. Seed-owned: questions live in
-- lib/programme/quiz-content.ts and nothing in the app edits config_json,
-- so re-running the seed is how an edited question reaches an existing
-- track. Also repairs a pass_mark or question_count left over from an
-- earlier version of the spec.
update public.programme_track_items i
   set config_json = s.config_json
  from (values
    (5, 3, '{"pass_mark":8,"question_count":10,"summative":false,"questions":[{"day":1,"question":"In an ordinary Chat, with web search turned off and no Connectors enabled, you ask Claude for the current list price of a product line. It answers with a precise figure, to the penny. Where did that number come from?","options":["It looked the price up and reported back what it found","It calculated it from related figures that it does hold","It predicted a plausible figure from patterns in its training data","It reported the last value it saw, so it is current unless the price moved","It inferred it from your earlier messages in this Chat"],"correct":2,"explanation":"Nothing was looked up. Claude predicts what comes next, so a figure arrives in whatever shape the surrounding sentence calls for, and two decimal places is a writing habit rather than evidence. When the number is right, that is training data agreeing with reality. Anything that moves needs a Connector or a source you open yourself."},{"day":1,"question":"Two hours into a long Chat, Claude starts breaking a formatting rule you set at the very beginning and had been following all along. What is the likeliest cause?","options":["It has decided your later instructions override the earlier one","The Chat has outgrown what Claude can hold in view at once","Output quality degrades over a long session, so it needs restarting","Its training data disagrees with the rule that you set","The rule was not stated firmly enough for it to stick"],"correct":1,"explanation":"Everything Claude can see has to fit in one window, and a long Chat pushes the beginning of it out of range. Restating the rule, or carrying the essentials into a fresh Chat, fixes it. Saying it more firmly does not, because the instruction is not being defied, it is not being seen."},{"day":2,"question":"Which of these is the weakest candidate for handing to Claude?","options":["Drafting the first version of a recurring internal update","Summarising a supplier contract you will read properly afterwards","Signing off the final numbers in the month-end pack","Reformatting a messy stock export into a consistent structure","Drafting a tender rejection letter that is reviewed before it goes"],"correct":2,"explanation":"Drafting, summarising and reformatting are where Claude earns its keep, and an awkward subject does not change that while the draft is reviewed before it goes. Signing off is the one that cannot move, because accountability is not a task. Use Claude to prepare what informs the decision rather than to make it."},{"day":2,"question":"Two colleagues use Claude on similar work. One handed over a whole process end to end and is disappointed. The other handed over only the drafting and is not. What explains the gap?","options":["The second colleague simply writes better prompts than the first","Judgement and accountability do not transfer, but drafting does","The first colleague is working on genuinely more complex material","The second colleague has been using the tool for a lot longer","The first colleague needs a Project and the second already has one"],"correct":1,"explanation":"Complexity is not the dividing line and neither is fluency with the tool. What transfers is the blank page and the repetitive middle. What does not is deciding and owning the result, so a process handed over whole always disappoints at the point where somebody has to be answerable. Prompting and Projects both help, and neither moves that line."},{"day":3,"question":"A prompt in a Chat returns content that is accurate and complete, but it reads like a different company wrote it. Which part of CRISPE is missing?","options":["Context","Instructions","Parameters","Role","Style"],"correct":4,"explanation":"Style is tone, register and voice. The content being right tells you Context and Instructions did their job. Role changes the expertise Claude writes from rather than the voice it writes in, and Parameters constrain length, format and what to leave out. When output is correct but reads wrong, Style is the gap."},{"day":3,"question":"You have to write this month''s report in exactly the same shape as last month''s: the same sections, in the same order, with the same kind of summary at the top. Which part of CRISPE does most of the work?","options":["Instructions, listing out every formatting rule you can think of first","Example, pasting last month''s report so it can copy the shape","Parameters, specifying the length and the number of sections","Context, explaining who reads the report and what they need from it","Role, so it writes as the person who produced the original one"],"correct":1,"explanation":"One example carries more specification than a page of rules, and it removes the ambiguity a description always leaves behind. Parameters and Instructions can approximate the shape and never the phrasing. Role and Context change how Claude thinks rather than what it hands you."},{"day":4,"question":"Every week you paste the same background into a new Chat before you can ask your real question: your team''s terminology, the format you need and the standing constraints. What fixes that properly?","options":["Keep the preamble in a note and paste it at the top of each Chat","Write one much longer prompt so that nothing important gets missed","Ask Claude to remember the background at the end of each Chat","Put the background and reference files in a Project","Add a Connector to the systems that background describes"],"correct":3,"explanation":"A Project holds standing context, so every Chat inside it starts briefed and nobody maintains a preamble by hand. A pasted note drifts the moment the format changes and a longer prompt moves the repetition rather than removing it. A Connector fetches live state, which is a different problem from standing background."},{"day":4,"question":"A Project you built answers the exact question you built it around very well, and anything slightly different badly. What does that tell you?","options":["The knowledge files you gave it are too small to generalise from","Projects are built for one job, so varied work belongs in a Chat","The instructions describe one task rather than how you work","You need a separate Project for each question you want to ask","Requests have to be phrased the way you phrased the original one"],"correct":2,"explanation":"A Project that only answers its founding question is a saved prompt with extra steps. Standing context is the method, the vocabulary and the constraints, and those carry across requests. Splitting it per question multiplies what you maintain and teaches the same lesson again a month later."},{"day":5,"question":"Several times a day you copy the same figures out of the same system and paste them into a Chat. What is that a signal for?","options":["A Connector, so Claude can reach the system itself","A longer prompt that carries more of the background with it","A Project holding the most recent export of those figures","Nothing, copy and paste is perfectly fine at that volume","A Scheduled Task that pastes the figures in for you each morning"],"correct":0,"explanation":"Repetitive copy and paste is the clearest signal that a Connector pays for itself. A Project holds context that changes slowly, and an export dropped into one is stale the moment it is saved. A schedule automates the ferrying rather than removing it, which leaves you the same stale figures on a timer."},{"day":5,"question":"A colleague worries that connecting a system to Claude will expose data they are not allowed to see. Which of the following is correct?","options":["They are right, a Connector reads the system and bypasses its permissions","Connectors are limited to data that the system already publishes openly","It depends entirely on which Connector and which system it is","It is safe provided they enable only the permissions the job needs","A Connector works within the access they already have"],"correct":4,"explanation":"A Connector is a route rather than a promotion, so their existing access is the ceiling. Checking the permissions a Connector allows by default is good practice and the day''s task asks for it, and it is still not what makes the answer safe. Worth being clear on in a regulated business, because the fear is common and it stops people using something useful."}]}'::jsonb),
    (10, 3, '{"pass_mark":8,"question_count":10,"summative":false,"questions":[{"day":6,"question":"You have a reliable method for a recurring task and two colleagues want to use it. What makes a Skill the right home for it, rather than a Project or a saved prompt?","options":["They turn it on once, then it fires by itself","It stores the documents the task needs alongside the method","It runs to a timetable, whether or not the job came up","It gives Claude access to the system that the task depends on","It keeps the method private to the colleagues you name on it"],"correct":0,"explanation":"A Skill packages how you do something so other people''s Chats can reach it: a colleague switches it on once, and from then on its description is what makes it fire without being named. Documents are a Project, a timetable is a Scheduled Task and system access is a Connector. Choosing the wrong container is what makes simple work feel like overhead."},{"day":6,"question":"You built a Skill and it never fires unless you name it explicitly in the Chat. What is almost always wrong?","options":["The instructions inside the Skill have grown too long to parse","It has to be shared with your team before it will trigger at all","The task is too narrow for a Skill to be the right container","Its description is too vague to match what people actually ask","Skills only fire automatically for the person who created them"],"correct":3,"explanation":"The description is the trigger. Use this when formatting a monthly performance report fires when it should, and helps with reports never fires at all. Sharing changes who can reach a Skill rather than whether it triggers, and a narrow task is exactly what a Skill wants."},{"day":7,"question":"From Scheduled in the sidebar you set a task to run the stock summary at 07:00 each Monday. You reach your desk at 08:30 and your laptop was shut overnight. What happens?","options":["It waits until you open the laptop, so the result arrives late","It ran at 07:00 without your machine, and the result is waiting","It is skipped entirely and runs again the following Monday","It fails, and you get a notification telling you that it failed","It ran at 07:00 but could not reach your Connectors while you were away"],"correct":1,"explanation":"Scheduled runs happen on Anthropic''s servers, so they keep their cadence with your computer asleep and the desktop app shut, and your connected tools go with them. Nothing is deferred, skipped or failed. The one thing that does still need your machine is a task reaching files or apps on it, which is why a schedule is built on your Connectors and the files saved to your Claude account rather than on a folder."},{"day":7,"question":"A Scheduled Task you set up three weeks ago still runs, but you now rewrite most of its output before you use it. What should you do?","options":["Leave it running, since it is still saving you time overall","Delete it and go back to doing the whole task by hand again","Run it more often so that its output stays closer to current","Keep it, and log the saving as the full time the task once took","Fold what you keep rewriting back in, or retire the task"],"correct":4,"explanation":"Heavy editing means the task and the real work have drifted apart, and what you keep rewriting is the specification. Running it more often just produces more to correct. Logging the old full cost is how a time saving becomes a number nobody believes, because the saving is what the job costs now against what it cost before."},{"day":8,"question":"You have asked Claude for a checklist your team will use every week. Why ask for it as an Artifact rather than as text in the Chat?","options":["Artifacts are generated faster than the same answer in a Chat","Claude is more accurate when it writes into an Artifact","You get something you can edit, version and share on its own","It uses fewer messages, so you get more out of your limits","Anyone you share it with can edit your copy of it directly"],"correct":2,"explanation":"An Artifact is the output as an object rather than as Chat scrollback: refined in place, every version kept, and shareable to people who need the checklist rather than the conversation behind it. Speed and accuracy are unchanged. Sharing lets other people open and use it, which is not the same as handing them edit rights on yours."},{"day":8,"question":"You have built a margin calculator as an Artifact in Claude and you are about to share the link so your team can use it. This quarter''s real supplier prices are typed into it. What has to happen first?","options":["Share it, then message the team asking them not to forward the link","Nothing, a shared Artifact is reachable only by the people you send it to","Swap the real prices for made-up ones before you share it","Leave the real prices in and write a confidentiality note at the top of the page","Share it with only the two colleagues who actually need it"],"correct":2,"explanation":"Sharing is the step that changes who can see something: on our plan a shared Artifact opens for anyone at Phlo with the link, not just the people you had in mind, and it carries the files attached to the conversation that built it along with it. Plenty of them have no business seeing supplier pricing, which is what makes live figures the wrong thing to leave in. A confidentiality note changes nothing about who can open the page, asking colleagues not to forward a link is not a control, and a share cannot be narrowed to two named people: the choice is everyone in the organisation or nobody."},{"day":9,"question":"Which of these is the strongest candidate for Cowork rather than an ordinary Chat?","options":["A question you need a single short answer to before this afternoon","Drafting an email to a supplier about a late delivery","Deciding which of two suppliers your team should move to","Working through a live document with a colleague at the same time","Merging six monthly reports into one summary and filing them"],"correct":4,"explanation":"Cowork earns its keep on assembly across many files on your own machine: work that is tedious rather than difficult, and that ends in files rather than in an answer. A short question and a draft are ordinary Chat, deciding is yours to own, and a Cowork session cannot be worked on by two people at once, so anything live and shared belongs elsewhere."},{"day":9,"question":"You are handing a job to Cowork in the desktop app and you have skipped the permission prompts so it can work without stopping to ask. What is keeping it away from files it has no business opening?","options":["The folder you pointed it at, and whatever you chose to put in it","Claude''s judgement about which of your files the task actually needs","The one-sentence brief, which tells it what it is allowed to open","The desktop app, which reaches your Claude account rather than your disk","Nothing much, so read every file it touched once the run has finished"],"correct":0,"explanation":"Skipping the prompts is what makes the folder the control. There is no per-step approval left, so the only thing between Cowork and a file is whether you put that file in scope before the run started. Claude cannot know which of your documents are commercially sensitive. A brief describes the goal rather than granting access, and the desktop app is the route to your disk rather than a limit on it: on our plan the run itself happens on Anthropic''s servers and reaches your files through that app, for the folders you connected and no others. Reading afterwards is worth doing but it is not a boundary, because by then it has opened whatever was there."},{"day":10,"question":"You need a pitch deck for Monday and you want to shape the layout before it goes out. Where does Claude Design earn its place over an ordinary Chat?","options":["It writes the words on each slide more accurately than a Chat does","It signs the deck off, so nobody else has to review what it made","It keeps the deck''s source documents attached for the next revision","You shape the layout on a canvas and export the result as a PPTX","It is the only surface at Phlo that can read a PowerPoint file"],"correct":3,"explanation":"The gain is a canvas plus a real export. You adjust spacing, colour and layout directly, or ask for changes in plain English, and the Export button gives you PowerPoint, PDF or a standalone page. A Chat can draft the words but hands them back as text for you to reassemble. Keeping source documents for next time is what a Project is for. Nothing here removes the human review, and a Chat reads a PowerPoint file perfectly well."},{"day":10,"question":"Which of the following is the poorest fit for Claude Design as it stands today?","options":["An internal one-pager explaining a process change to your team","A rough settings screen, made to get a conversation started","A patient-facing leaflet going out under Phlo''s brand","A slide for Monday''s team meeting that you will talk over","A layout you want to react to before committing real time to it"],"correct":2,"explanation":"Two things make it the wrong fit. It is a research preview, so what comes out is a draft rather than a finished brand, and patient-facing material has to meet a standard a draft is not aiming at. Confidential designs and private code stay out for the same reason. Internal drafts, rough screens and something to react to are exactly the work it is for."}]}'::jsonb),
    (15, 3, '{"pass_mark":8,"question_count":10,"summative":true,"questions":[{"day":11,"question":"You need a written comparison of three couriers'' terms, ready to send on. Which approach uses what Claude is actually good at?","options":["Ask for the comparison, then copy the answer out of the Chat by hand","Ask three separate questions and stitch the answers together yourself","Ask for bullet points in a Chat and write the document up yourself","Ask Research to compare all three and hand back a finished file","Ask for the comparison, paste it into a document and format it"],"correct":3,"explanation":"Research searches, reads and cross-references, then hands back the finished file rather than leaving you to reassemble a document out of Chat text, and it runs in the background while you do something else. Every other option ends with you doing the part the tool would have done."},{"day":11,"question":"You turn Memory on and Claude starts carrying your role, your team''s terminology and your usual formats between Chats. What does that change?","options":["Factual answers get more reliable, because it knows your situation","You stop re-briefing it at the start of every Chat, nothing more","It can now reach your company systems without needing a Connector","Your Chats become visible to colleagues who share the same memory","It stops inventing detail on topics it now holds context about"],"correct":1,"explanation":"Memory removes the re-briefing. It does not turn a prediction into a lookup, so the checking habit is untouched, and knowing your team''s vocabulary does not stop Claude inventing a figure. It grants no system access, which is what a Connector is for, and it shares nothing with anyone."},{"day":12,"question":"You have reworded a prompt three times and the answer keeps coming back the same shape of wrong. What does the programme tell you to do next?","options":["Reword it once more, being precise about the format you want","Start a fresh Chat, on the basis that this one is confused","Accept that the job is outside what the tool can do for you","Ask Claude to interview you about what it needs, then answer","Add more context in bulk until the answer eventually shifts"],"correct":3,"explanation":"The same wrong shape repeating means the gap is in what you have not said rather than in how you said it, and no rewrite reaches that. Letting Claude ask what it needs surfaces the context you were assuming without noticing. One poor answer is normal and a follow-up is just conversation - it is the repetition that is the signal. A fresh Chat and bulk context are the same guess made again."},{"day":13,"question":"Claude keeps failing at a job you have given it. How do you tell a prompting problem from a capability problem?","options":["It misunderstood you is prompting; it cannot reach that is capability","A slow job means it is straining against a limit, so capability","A confident wrong answer means a capability gap rather than wording","Capability problems always show an error, so anything else is wording","It rarely matters, because better prompting helps in both cases"],"correct":0,"explanation":"Prompting changes how well you use what is already there. Plugins change what is there. The diagnosis is where the time goes, because rewriting a prompt against a capability gap can absorb an afternoon and never work. Capability gaps rarely announce themselves, and a confident wrong answer is a verification problem rather than a capability one."},{"day":14,"question":"You spend most of your day in Excel and Slack, and Claude is available inside both. What follows from that?","options":["You should still work in the Claude app and paste results across","The in-tool versions are weaker, so avoid them for real work","It only matters for people who work mostly in documents","It matters most for long tasks, which are worth setting up for","Small jobs stop being worth skipping, because the switch is gone"],"correct":4,"explanation":"The barrier was rarely capability, it was friction. Stopping, switching app, re-explaining the context and pasting the answer back is enough to make anyone skip a two-minute job, and small jobs are where most of the saving quietly adds up. Long tasks were always worth the switch, so they are not where this changes anything."},{"day":15,"question":"You are totalling up what the three weeks saved you. For the job you claim the biggest saving on, the before figure and the after figure are both ones you remembered. What is the problem?","options":["Nothing is wrong, you ran the job both ways so both figures are yours","The before figure will be inflated, because slow work feels longer","Neither figure was measured, so the saving is a guess with a decimal","The saving belongs to the team rather than to you, so it double counts","Three weeks is too short a window to draw any saving from at all"],"correct":2,"explanation":"Remembered numbers drift in the direction you want them to go, and the before figure drifts furthest because the old way is the one you resented. One timed run is worth more than fifteen estimates. It is also the only version of the figure that survives somebody outside the programme asking how you arrived at it, which is the question this whole exercise is preparing you for."},{"day":15,"question":"You have halved the time your weekly report takes by drafting it in a Chat. You now spend ten minutes checking figures you used to take straight from the system. How should that land in your total?","options":["Leave it out, checking is overhead rather than part of the job","Subtract it, because the job is not finished until it is checked","Count it separately, as a cost of Claude rather than a cost of the job","Ignore it, the checking tails off once the drafting has earned trust","Halve it, since you would have checked some of those figures anyway"],"correct":1,"explanation":"The number worth having is the one you could defend to somebody outside the programme, and that is the job end to end rather than the drafting step on its own. Checking is not overhead bolted onto the work, it is the part that makes the output usable. A total that quietly drops it is the kind of figure that falls apart the first time anyone asks how it was built."},{"day":3,"question":"A prompt keeps producing output that is accurate but consistently the wrong length and format for where it has to go. Which part of CRISPE do you reach for?","options":["Context","Role","Instructions","Parameters","Example"],"correct":3,"explanation":"Parameters are the constraints: length, format, structure and what to leave out. Context and Role shape what Claude knows and how it thinks, and Instructions say what to do rather than what shape to do it in. An Example would work too, and it costs you a document to paste; when the content is already right, Parameters is the smaller lever."},{"day":5,"question":"Your team has a Project full of reference documents and a Connector to the system those documents describe. When does the Connector earn its keep?","options":["When you need what the system says now, not what it said then","Always, because a Connector is the more capable feature of the two","Only once the Project grows too large to search reliably","Never, since the two of them do the same job by other means","When the documents in the Project are more than a month old"],"correct":0,"explanation":"A Project holds standing context that changes slowly and a Connector fetches live state. Reference material belongs in the Project and anything that moves belongs behind the Connector, whatever its age: a document goes stale when the system changes rather than after a set period. Treating a stored document as current is a quiet source of wrong answers."},{"day":7,"question":"You have a recurring task, a one-off question, a method colleagues should reuse and a system Claude cannot reach. Which mapping is right?","options":["Skill, Scheduled Task, Project, Connector","Project, Skill, Connector, Plugin","Scheduled Task, Chat, Skill, Connector","Connector, Artifact, Scheduled Task, Skill","Scheduled Task, Chat, Project, Connector"],"correct":2,"explanation":"Recurring and predictable is a Scheduled Task, a one-off just needs a Chat, a repeatable method other people can run is a Skill and reaching a system is a Connector. The near miss puts a Project in the third slot: a Project holds standing context for your own Chats rather than packaging a method somebody else''s Chat can trigger. Choosing the wrong container is what makes simple work feel like overhead."}]}'::jsonb)
  ) as s(day_index, sort_order, config_json)
 where i.day_index = s.day_index and i.sort_order = s.sort_order
   and i.type = 'quiz'
   and i.track_id = (select id from public.programme_tracks where slug = 'core-programme')
   and i.config_json is distinct from s.config_json;

-- Re-bind any day whose Learn video has since been added. Only fills nulls,
-- so an admin's manual binding is never overwritten.
--
-- VIDEO ITEMS ONLY. A use_example is the "now go do it" half of the day and
-- stays unbound: if it shared the video, one tick on /learn would complete
-- both items and G1 would be reachable without doing any exercise.
update public.programme_track_items i
   set learn_video_id = v.id
  from public.learn_videos v
 where i.learn_video_id is null
   and i.type = 'video'
   and lower(v.title) = lower(i.title)
   and i.track_id = (select id from public.programme_tracks where slug = 'core-programme');
